import{_ as e,o as a,c as o,a7 as d}from"./chunks/framework.D9zuiyJR.js";const g=JSON.parse('{"title":"FAQ","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://zilero232.github.io/commit-jazzer/guide/faq"}]]},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md","lastUpdated":1792407534000}'),i={name:"guide/faq.md"};function r(s,t,n,h,c,m){return a(),o("div",null,[...t[0]||(t[0]=[d('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><h2 id="the-hook-does-not-ask-anything" tabindex="-1">The hook does not ask anything <a class="header-anchor" href="#the-hook-does-not-ask-anything" aria-label="Permalink to &quot;The hook does not ask anything&quot;">​</a></h2><ul><li>The hook skips commits that already have a message: <code>git commit -m</code>, <code>-F</code>, merges, squashes and <code>--amend</code>.</li><li>It also skips commits without a terminal: IDE git panels, GUI clients, and Windows, where Node cannot open the terminal of a hook. git then opens its editor as usual.</li><li>A hook in <code>.git/hooks</code> must be executable: <code>chmod +x .git/hooks/prepare-commit-msg</code>.</li><li><code>core.hooksPath</code> set by another tool? <code>jazzer init --hook</code> writes the hook there; with husky it goes to <code>.husky/</code>.</li><li>With <code>commit.template</code> set, git reports every commit as a template commit, and the hook leaves those alone.</li></ul><h2 id="npx-jazzer-runs-something-else" tabindex="-1"><code>npx jazzer</code> runs something else <a class="header-anchor" href="#npx-jazzer-runs-something-else" aria-label="Permalink to &quot;`npx jazzer` runs something else&quot;">​</a></h2><p><code>jazzer</code> is the command name, not the package name. Before installing, run <code>npx commit-jazzer</code>; after <code>npm install --save-dev commit-jazzer</code>, <code>npx jazzer</code> works too.</p><h2 id="commitizen-uses-an-old-inquirer-does-that-matter" tabindex="-1">Commitizen uses an old Inquirer. Does that matter? <a class="header-anchor" href="#commitizen-uses-an-old-inquirer-does-that-matter" aria-label="Permalink to &quot;Commitizen uses an old Inquirer. Does that matter?&quot;">​</a></h2><p>No. Commitizen passes its Inquirer 8 to the adapter; commit-jazzer ignores it and uses the current <code>@inquirer</code> prompts.</p><h2 id="how-do-i-commit-with-a-message-i-already-have" tabindex="-1">How do I commit with a message I already have? <a class="header-anchor" href="#how-do-i-commit-with-a-message-i-already-have" aria-label="Permalink to &quot;How do I commit with a message I already have?&quot;">​</a></h2><p><code>git commit -m &quot;…&quot;</code> as usual. With the hook installed it is left alone.</p><h2 id="a-hook-rejected-my-commit-do-i-have-to-answer-everything-again" tabindex="-1">A hook rejected my commit. Do I have to answer everything again? <a class="header-anchor" href="#a-hook-rejected-my-commit-do-i-have-to-answer-everything-again" aria-label="Permalink to &quot;A hook rejected my commit. Do I have to answer everything again?&quot;">​</a></h2><p>No: <code>jazzer --retry</code> commits the last message again. The message of a <code>jazzer</code> commit that failed stays in <code>.git/commit-jazzer/last-message</code> until a commit goes through. Messages of the hook and of <code>git cz</code> are not stored there, but git keeps them in <code>.git/COMMIT_EDITMSG</code>.</p><h2 id="can-i-use-it-without-a-terminal" tabindex="-1">Can I use it without a terminal? <a class="header-anchor" href="#can-i-use-it-without-a-terminal" aria-label="Permalink to &quot;Can I use it without a terminal?&quot;">​</a></h2><p>Yes. Pass the required answers as flags; see <a href="./recipes#scripts-ci-and-coding-agents">Scripts, CI and coding agents</a>.</p><h2 id="how-does-it-compare-to-other-tools" tabindex="-1">How does it compare to other tools? <a class="header-anchor" href="#how-does-it-compare-to-other-tools" aria-label="Permalink to &quot;How does it compare to other tools?&quot;">​</a></h2><p>As of October 2026, from the documentation of each tool:</p><table tabindex="0"><thead><tr><th></th><th>commit-jazzer</th><th><a href="https://cz-git.qbb.sh" target="_blank" rel="noreferrer">cz-git / czg</a></th><th><a href="https://github.com/carloscuesta/gitmoji-cli" target="_blank" rel="noreferrer">gitmoji-cli</a></th><th><a href="https://github.com/Everduin94/better-commits" target="_blank" rel="noreferrer">better-commits</a></th></tr></thead><tbody><tr><td>Standalone CLI</td><td>✅</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td>Commitizen adapter</td><td>✅</td><td>✅</td><td>—</td><td>—</td></tr><tr><td><code>prepare-commit-msg</code> hook</td><td>✅</td><td>✅</td><td>✅</td><td>—</td></tr><tr><td>Conventional Commits output</td><td>✅</td><td>✅</td><td>— (<code>:emoji: (scope): title</code>)</td><td>✅</td></tr><tr><td>Non-interactive flags</td><td>✅</td><td>aliases</td><td>prefill only</td><td>✅</td></tr><tr><td>Reads the commitlint config</td><td>scopes, lengths</td><td>✅</td><td>—</td><td>—</td></tr><tr><td>Type and ticket from the branch</td><td>✅</td><td>via recipe</td><td>—</td><td>✅</td></tr><tr><td>Config</td><td>JSON / TS / JS / <code>package.json</code></td><td>JS / TS / commitlint config</td><td>JSON / <code>package.json</code></td><td>JSONC</td></tr><tr><td>Built-in prompt translations</td><td>13 languages</td><td>— (texts are configurable)</td><td>—</td><td>—</td></tr><tr><td>AI suggestions</td><td>—</td><td>✅</td><td>—</td><td>—</td></tr></tbody></table><p>Pick cz-git if you want AI messages or one config file shared with commitlint; gitmoji-cli if you want gitmoji&#39;s own format.</p><h2 id="how-do-i-add-a-language" tabindex="-1">How do I add a language? <a class="header-anchor" href="#how-do-i-add-a-language" aria-label="Permalink to &quot;How do I add a language?&quot;">​</a></h2><p>Copy <code>src/core/i18n/locales/en.json</code>, translate the values, and add the language to <code>LANGUAGES</code> in <code>src/shared/constants.ts</code> and to <code>src/core/i18n/i18n.ts</code>. A test checks that every language has the same keys and placeholders.</p>',19)])])}const u=e(i,[["render",r]]);export{g as __pageData,u as default};
